import java.util.*;class Solution{List<List<Integer>>o=new ArrayList<>();void f(int[]a,boolean[]u,List<Integer>v){if(v.size()==a.length){o.add(new ArrayList<>(v));return;}for(int i=0;i<a.length;i++){if(u[i]||(i>0&&a[i]==a[i-1]&&!u[i-1]))continue;u[i]=true;v.add(a[i]);f(a,u,v);v.remove(v.size()-1);u[i]=false;}}public List<List<Integer>> permuteUnique(int[]a){Arrays.sort(a);f(a,new boolean[a.length],new ArrayList<>());return o;}}
